def safe_projection(graph):
 receipts=graph["receipts"]; files=graph["files"]; omissions=graph["omissions"]
 statuses={s:sum(x.status==s for x in receipts) for s in ("complete","partial","unavailable","omitted","blocked")}
 return {"baseline":"synthetic_local","candidate":"customer-account-portability","packageStatus":graph["packageStatus"],"domainStatusCounts":statuses,"configuredDomains":10,"representedDomains":len(receipts),"fileCount":len(files),"omissionCount":len(omissions),"cutoffKindCounts":{k:sum(p.cutoff.kind==k for p in graph["plans"]) for k in ("convex_revision","timescale_watermark","public_chain_reference")},"verification":"verified" if graph["verification"].verified else "failed","grantState":graph["grant"].state,"deliveryState":graph["delivery"].state,"cleanupState":graph["cleanup"].state,"reasons":list(graph["reasons"]),"manifestHash":graph["manifest"].manifest_hash[:12],"rootHash":graph["root"].root_hash[:12],"fixtureOnly":True,"productOutcome":"unavailable","downloadAvailable":False,"operationPerformed":False,"authorityEffect":"none","externalAttempts":0,"providerCost":0}
